#include <stdio.h>
int sum_many(int a, int b, int c, int d, int e, int f) {
    return a + b + c + d + e + f;
}
void mutate(int *p, int val) {
    *p = val;
}
int main() {
    int s = sum_many(41, 42, 43, 44, 45, 46);
    printf("sum: %d\n", s);
    int x = 0;
    mutate(&x, 4100);
    printf("mutated: %d\n", x);
    return 0;
}
